.message-log .log-warning {
    background: #fff3cd;
    color: #856404;
}

.message-log .log-error {
    background: #f8d7da;
    color: #721c24;
}

/* Map Container Styles */
.map-container {
    position: relative;
    height: 100%;
    background: var(--panel-bg);
    border: 1px solid var(--border-color);
    border-radius: 8px;
    overflow: hidden;
}

.map-controls {
    position: absolute;
    top: 10px;
    left: 10px;
    z-index: 1000;
    display: flex;
    gap: 0.5rem;
    background: rgba(255, 255, 255, 0.9);
    padding: 0.5rem;
    border-radius: 4px;
    backdrop-filter: blur(5px);
