}

.armed-status {
    padding: 0.5rem 1rem;
    border-radius: 4px;
    font-weight: 600;
    font-size: 1.1rem;
    text-align: center;
    background: var(--danger-color);
    color: white;
}

.armed-status.armed {
    background: var(--success-color);
}

.flight-mode {
    padding: 0.5rem 1rem;
    background: var(--light-color);
    border-radius: 4px;
    font-weight: 500;
}

.pfd-telemetry {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.telemetry-row {
    display: flex;
    justify-content: space-between;
