}

/* Request Controls and Audio Styles */
.request-panel h3 {
    display: none;
}

.request-buttons {
    display: flex;
    gap: 0.5rem;
}

.audio-controls {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
}

.checkbox-label {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    cursor: pointer;
    font-size: 0.9rem;
