/**
 * WebGCS Telemetry Display Module
 * Handles Primary Flight Display (PFD) with attitude indicator and instrument tapes
 */

window.TelemetryDisplay = (function() {
    'use strict';

    // Private variables
    let telemetryData = {};
    let animationFrameId = null;

    // Canvas contexts
    let contexts = {};

    // DOM elements
    let elements = {};

    /**
     * Initialize Telemetry Display
     */
    function initialize() {
        console.log('Initializing Telemetry Display...');

        // Cache DOM elements
        cacheElements();

        // Initialize canvases
        initializeCanvases();

        // Setup event listeners
        setupEventListeners();

        // Start animation loop
        startAnimationLoop();

        console.log('Telemetry Display initialized');
    }

    /**
     * Cache DOM Elements
     */
    function cacheElements() {
        elements = {
            // Canvas elements
            attitudeIndicator: document.getElementById('attitude-indicator'),
            airspeedTape: document.getElementById('airspeed-tape'),
            altitudeTape: document.getElementById('altitude-tape'),

            // Status elements
            armedStatus: document.getElementById('armed-status'),
            flightMode: document.getElementById('flight-mode'),

            // Telemetry elements
            batteryVoltage: document.getElementById('battery-voltage'),
            currentDraw: document.getElementById('current-draw'),
            gpsStatus: document.getElementById('gps-status'),
            positionDisplay: document.getElementById('position-display')
        };

        // Check for missing elements
        Object.entries(elements).forEach(([key, element]) => {
            if (!element) {
                console.warn(`Telemetry Display: Element '${key}' not found`);
            }
        });
    }

    /**
     * Initialize Canvas Contexts
     */
    function initializeCanvases() {
        const canvasElements = ['attitudeIndicator', 'airspeedTape', 'altitudeTape'];

        canvasElements.forEach(name => {
            const canvas = elements[name];
            if (canvas && canvas.getContext) {
                contexts[name] = canvas.getContext('2d');

                // Set high DPI support
                const ctx = contexts[name];
                const dpr = window.devicePixelRatio || 1;
                const rect = canvas.getBoundingClientRect();

                canvas.width = rect.width * dpr;
                canvas.height = rect.height * dpr;
                ctx.scale(dpr, dpr);

                // Set initial styling
                ctx.textAlign = 'center';
                ctx.textBaseline = 'middle';
                ctx.font = '12px Arial, sans-serif';
            }
        });
    }

    /**
     * Setup Event Listeners
     */
    function setupEventListeners() {
        // Listen for global events
        if (window.WebGCS && window.WebGCS.eventBus) {
            window.WebGCS.eventBus.addEventListener('telemetry_updated', handleTelemetryUpdate);
            window.WebGCS.eventBus.addEventListener('connection_changed', handleConnectionChange);
        }

        // Handle window resize for canvas scaling
        window.addEventListener('resize', handleResize);
    }

    /**
     * Start Animation Loop
     */
    function startAnimationLoop() {
        function animate() {
            updateAllDisplays();
            animationFrameId = requestAnimationFrame(animate);
        }
        animate();
    }

    /**
     * Update All Displays
     */
    function updateAllDisplays() {
        drawAttitudeIndicator();
        drawAirspeedTape();
        drawAltitudeTape();
        updateTextualDisplays();
    }

    /**
     * Draw Professional Attitude Indicator (G1000-style Artificial Horizon)
     */
    function drawAttitudeIndicator() {
        const ctx = contexts.attitudeIndicator;
        if (!ctx) return;

        const canvas = elements.attitudeIndicator;
        const width = canvas.clientWidth;
        const height = canvas.clientHeight;
        const centerX = width / 2;
        const centerY = height / 2;
        const radius = Math.min(width, height) / 2 - 20;

        // Clear canvas with dark background
        ctx.fillStyle = '#000011';
        ctx.fillRect(0, 0, width, height);

        // Get attitude data
        const pitch = telemetryData.pitch || 0; // In degrees
        const roll = telemetryData.roll || 0;   // In degrees

        // Save context
        ctx.save();

        // Translate to center
        ctx.translate(centerX, centerY);

        // Draw horizon background
        ctx.save();

        // Rotate by roll angle
        ctx.rotate(roll * Math.PI / 180);

        // Create clipping circle
        ctx.beginPath();
        ctx.arc(0, 0, radius, 0, Math.PI * 2);
        ctx.clip();

        // Calculate pitch offset (aviation standard: 4 pixels per degree)
        const pitchPixels = pitch * 4;

        // Draw sky gradient (aviation blue)
        const skyGradient = ctx.createLinearGradient(0, -radius, 0, pitchPixels);
        skyGradient.addColorStop(0, '#4169E1'); // Royal blue at top
        skyGradient.addColorStop(1, '#87CEEB'); // Sky blue at horizon
        ctx.fillStyle = skyGradient;
        ctx.fillRect(-radius, -radius, radius * 2, radius + pitchPixels);

        // Draw ground gradient (aviation brown)
        const groundGradient = ctx.createLinearGradient(0, pitchPixels, 0, radius);
        groundGradient.addColorStop(0, '#8B4513'); // Saddle brown at horizon
        groundGradient.addColorStop(1, '#2F1B14'); // Dark brown at bottom
        ctx.fillStyle = groundGradient;
        ctx.fillRect(-radius, pitchPixels, radius * 2, radius * 2);

        // Draw horizon line (white)
        ctx.strokeStyle = '#FFFFFF';
        ctx.lineWidth = 3;
        ctx.beginPath();
        ctx.moveTo(-radius, pitchPixels);
        ctx.lineTo(radius, pitchPixels);
        ctx.stroke();

        // Draw professional pitch ladder
        drawPitchLadder(ctx, radius, pitchPixels);

        ctx.restore();

        // Draw professional aircraft symbol (white chevron bars)
        drawAircraftSymbol(ctx);

        // Draw outer bezel
        ctx.strokeStyle = '#4169E1';
        ctx.lineWidth = 3;
        ctx.beginPath();
        ctx.arc(0, 0, radius, 0, Math.PI * 2);
        ctx.stroke();

        // Draw professional roll scale
        drawProfessionalRollScale(ctx, radius);

        ctx.restore();
    }

    /**
     * Draw Professional Pitch Ladder (G1000-style)
     */
    function drawPitchLadder(ctx, radius, pitchOffset) {
        const pitchAngles = [-60, -45, -30, -20, -15, -10, -5, 0, 5, 10, 15, 20, 30, 45, 60];

        ctx.font = '12px "Courier New", monospace';
        ctx.textAlign = 'center';
        ctx.lineWidth = 2;

        pitchAngles.forEach(angle => {
            if (angle === 0) return; // Skip horizon line (already drawn)

            const y = pitchOffset - (angle * 4); // 4 pixels per degree

            if (Math.abs(y) > radius) return; // Skip if outside visible area

            const isAboveHorizon = angle > 0;
            const isMajorLine = Math.abs(angle) % 10 === 0;
            const lineLength = isMajorLine ? 80 : 40;
            const lineStyle = isMajorLine ? 2 : 1;

            // Set colors based on sky/ground
            ctx.strokeStyle = '#FFFFFF';
            ctx.fillStyle = '#FFFFFF';
            ctx.lineWidth = lineStyle;

            if (isMajorLine) {
                // Major pitch lines (solid)
                ctx.beginPath();
                ctx.moveTo(-lineLength / 2, y);
                ctx.lineTo(lineLength / 2, y);
                ctx.stroke();

                // Pitch angle numbers
                ctx.fillText(Math.abs(angle).toString(), -lineLength / 2 - 20, y + 4);
                ctx.fillText(Math.abs(angle).toString(), lineLength / 2 + 20, y + 4);
            } else if (Math.abs(angle) === 2.5 || Math.abs(angle) === 5) {
                // Minor pitch lines
                ctx.setLineDash([5, 5]);
                ctx.beginPath();
                ctx.moveTo(-lineLength / 2, y);
                ctx.lineTo(lineLength / 2, y);
                ctx.stroke();
                ctx.setLineDash([]);
            }

            // Draw chevron for 5-degree lines
            if (Math.abs(angle) % 5 === 0 && Math.abs(angle) % 10 !== 0) {
                const chevronSize = 8;
                ctx.beginPath();
                if (isAboveHorizon) {
                    // Upward chevron for climb
                    ctx.moveTo(-chevronSize, y + chevronSize);
                    ctx.lineTo(0, y);
                    ctx.lineTo(chevronSize, y + chevronSize);
                } else {
                    // Downward chevron for dive
                    ctx.moveTo(-chevronSize, y - chevronSize);
                    ctx.lineTo(0, y);
                    ctx.lineTo(chevronSize, y - chevronSize);
                }
                ctx.stroke();
            }
        });
    }

    /**
     * Draw Professional Aircraft Symbol (White Chevron Bars)
     */
    function drawAircraftSymbol(ctx) {
        ctx.strokeStyle = '#FFFFFF';
        ctx.fillStyle = '#FFFFFF';
        ctx.lineWidth = 3;

        // Center reference dot
        ctx.beginPath();
        ctx.arc(0, 0, 2, 0, Math.PI * 2);
        ctx.fill();

        // Left wing bar
        ctx.beginPath();
        ctx.moveTo(-35, 0);
        ctx.lineTo(-8, 0);
        ctx.lineTo(-8, -3);
        ctx.stroke();

        // Right wing bar
        ctx.beginPath();
        ctx.moveTo(35, 0);
        ctx.lineTo(8, 0);
        ctx.lineTo(8, -3);
        ctx.stroke();

        // Center fuselage reference
        ctx.beginPath();
        ctx.moveTo(0, -8);
        ctx.lineTo(0, 8);
        ctx.lineWidth = 2;
        ctx.stroke();
    }

    /**
     * Draw Professional Roll Scale (G1000-style Bank Angle Indicator)
     */
    function drawProfessionalRollScale(ctx, radius) {
        const roll = telemetryData.roll || 0;

        // Draw bank angle marks
        ctx.strokeStyle = '#FFFFFF';
        ctx.fillStyle = '#FFFFFF';
        ctx.lineWidth = 2;
        ctx.font = '11px "Courier New", monospace';
        ctx.textAlign = 'center';

        // Standard bank angle marks: 10°, 20°, 30°, 45°, 60°, 90°
        const bankMarks = [
            { angle: -90, length: 15, showNumber: true },
            { angle: -60, length: 12, showNumber: true },
            { angle: -45, length: 12, showNumber: true },
            { angle: -30, length: 10, showNumber: true },
            { angle: -20, length: 8, showNumber: false },
            { angle: -10, length: 8, showNumber: false },
            { angle: 0, length: 15, showNumber: false },
            { angle: 10, length: 8, showNumber: false },
            { angle: 20, length: 8, showNumber: false },
            { angle: 30, length: 10, showNumber: true },
            { angle: 45, length: 12, showNumber: true },
            { angle: 60, length: 12, showNumber: true },
            { angle: 90, length: 15, showNumber: true }
        ];

        bankMarks.forEach(mark => {
            const radian = (mark.angle - 90) * Math.PI / 180;
            const x1 = Math.cos(radian) * (radius - mark.length);
            const y1 = Math.sin(radian) * (radius - mark.length);
            const x2 = Math.cos(radian) * radius;
            const y2 = Math.sin(radian) * radius;

            ctx.beginPath();
            ctx.moveTo(x1, y1);
            ctx.lineTo(x2, y2);
            ctx.stroke();

            if (mark.showNumber && Math.abs(mark.angle) !== 90) {
                const textX = Math.cos(radian) * (radius + 15);
                const textY = Math.sin(radian) * (radius + 15);
                ctx.fillText(Math.abs(mark.angle).toString(), textX, textY + 4);
            }
        });

        // Draw roll pointer (inverted triangle)
        ctx.save();
        ctx.rotate(roll * Math.PI / 180);
        ctx.fillStyle = '#FFFF00'; // Yellow roll indicator
        ctx.strokeStyle = '#FFFFFF';
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(0, -radius - 8);
        ctx.lineTo(-6, -radius + 2);
        ctx.lineTo(6, -radius + 2);
        ctx.closePath();
        ctx.fill();
        ctx.stroke();
        ctx.restore();
    }

    /**
     * Draw Roll Scale
     */
    function drawRollScale(ctx, radius) {
        const roll = telemetryData.roll || 0;

        // Draw roll marks
        ctx.strokeStyle = '#333333';
        ctx.lineWidth = 2;

        const marks = [-60, -45, -30, -20, -10, 0, 10, 20, 30, 45, 60];
        marks.forEach(angle => {
            const radian = (angle - 90) * Math.PI / 180;
            const x1 = Math.cos(radian) * (radius - 10);
            const y1 = Math.sin(radian) * (radius - 10);
            const x2 = Math.cos(radian) * (radius + 5);
            const y2 = Math.sin(radian) * (radius + 5);

            ctx.beginPath();
            ctx.moveTo(x1, y1);
            ctx.lineTo(x2, y2);
            ctx.stroke();

            if ([0, 30, 60].includes(Math.abs(angle))) {
                ctx.font = '10px Arial';
                ctx.textAlign = 'center';
                ctx.fillStyle = '#333333';
                const textX = Math.cos(radian) * (radius + 15);
                const textY = Math.sin(radian) * (radius + 15);
                ctx.fillText(Math.abs(angle).toString(), textX, textY);
            }
        });

        // Draw roll indicator triangle
        ctx.fillStyle = '#FF0000';
        ctx.beginPath();
        ctx.moveTo(0, -radius - 10);
        ctx.lineTo(-5, -radius);
        ctx.lineTo(5, -radius);
        ctx.closePath();
        ctx.fill();
    }

    /**
     * Draw Airspeed Tape
     */
    function drawAirspeedTape() {
        const ctx = contexts.airspeedTape;
        if (!ctx) return;

        const canvas = elements.airspeedTape;
        const width = canvas.clientWidth;
        const height = canvas.clientHeight;

        // Clear canvas
        ctx.clearRect(0, 0, width, height);

        // Get airspeed data
        const airspeed = Math.sqrt(
            Math.pow(telemetryData.vx || 0, 2) + 
            Math.pow(telemetryData.vy || 0, 2)
        ); // Ground speed as proxy for airspeed

        // Draw tape background
        ctx.fillStyle = '#000000';
        ctx.fillRect(0, 0, width, height);

        // Draw speed marks
        const centerY = height / 2;
        const pixelsPerUnit = 5; // 5 pixels per m/s

        ctx.strokeStyle = '#FFFFFF';
        ctx.fillStyle = '#FFFFFF';
        ctx.lineWidth = 1;
        ctx.font = '12px Arial';
        ctx.textAlign = 'right';

        // Draw speed scale
        const minSpeed = Math.max(0, airspeed - 20);
        const maxSpeed = airspeed + 20;

        for (let speed = Math.floor(minSpeed); speed <= maxSpeed; speed++) {
            const y = centerY - (speed - airspeed) * pixelsPerUnit;

            if (y >= 0 && y <= height) {
                // Major marks every 5 m/s
                if (speed % 5 === 0) {
                    ctx.beginPath();
                    ctx.moveTo(width - 15, y);
                    ctx.lineTo(width, y);
                    ctx.stroke();

                    ctx.fillText(speed.toString(), width - 20, y + 3);
                } else {
                    // Minor marks
                    ctx.beginPath();
                    ctx.moveTo(width - 8, y);
                    ctx.lineTo(width, y);
                    ctx.stroke();
                }
            }
        }

        // Draw current speed box
        ctx.fillStyle = '#000000';
        ctx.strokeStyle = '#FFFFFF';
        ctx.lineWidth = 2;

        const boxWidth = 35;
        const boxHeight = 20;
        const boxX = width - boxWidth;
        const boxY = centerY - boxHeight / 2;

        ctx.fillRect(boxX, boxY, boxWidth, boxHeight);
        ctx.strokeRect(boxX, boxY, boxWidth, boxHeight);

        // Draw speed text
        ctx.fillStyle = '#FFFFFF';
        ctx.textAlign = 'center';
        ctx.font = '14px Arial';
        ctx.fillText(airspeed.toFixed(1), boxX + boxWidth / 2, centerY + 3);
    }

    /**
     * Draw Altitude Tape
     */
    function drawAltitudeTape() {
        const ctx = contexts.altitudeTape;
        if (!ctx) return;

        const canvas = elements.altitudeTape;
        const width = canvas.clientWidth;
        const height = canvas.clientHeight;

        // Clear canvas
        ctx.clearRect(0, 0, width, height);

        // Get altitude data
        const altitude = telemetryData.alt_rel || 0;

        // Draw tape background
        ctx.fillStyle = '#000000';
        ctx.fillRect(0, 0, width, height);

        // Draw altitude marks
        const centerY = height / 2;
        const pixelsPerUnit = 2; // 2 pixels per meter

        ctx.strokeStyle = '#FFFFFF';
        ctx.fillStyle = '#FFFFFF';
        ctx.lineWidth = 1;
        ctx.font = '12px Arial';
        ctx.textAlign = 'left';

        // Draw altitude scale
        const minAlt = altitude - 50;
        const maxAlt = altitude + 50;

        for (let alt = Math.floor(minAlt / 10) * 10; alt <= maxAlt; alt += 10) {
            const y = centerY - (alt - altitude) * pixelsPerUnit;

            if (y >= 0 && y <= height) {
                // Major marks every 10m
                ctx.beginPath();
                ctx.moveTo(0, y);
                ctx.lineTo(15, y);
                ctx.stroke();

                ctx.fillText(alt.toString(), 20, y + 3);

                // Minor marks every 5m
                const y5 = centerY - (alt + 5 - altitude) * pixelsPerUnit;
                if (y5 >= 0 && y5 <= height) {
                    ctx.beginPath();
                    ctx.moveTo(0, y5);
                    ctx.lineTo(8, y5);
                    ctx.stroke();
                }
            }
        }

        // Draw current altitude box
        ctx.fillStyle = '#000000';
        ctx.strokeStyle = '#FFFFFF';
        ctx.lineWidth = 2;

        const boxWidth = 45;
        const boxHeight = 20;
        const boxX = 0;
        const boxY = centerY - boxHeight / 2;

        ctx.fillRect(boxX, boxY, boxWidth, boxHeight);
        ctx.strokeRect(boxX, boxY, boxWidth, boxHeight);

        // Draw altitude text
        ctx.fillStyle = '#FFFFFF';
        ctx.textAlign = 'center';
        ctx.font = '14px Arial';
        ctx.fillText(altitude.toFixed(1), boxX + boxWidth / 2, centerY + 3);
    }

    /**
     * Update Textual Displays
     */
    function updateTextualDisplays() {
        // Armed status
        if (elements.armedStatus) {
            const armed = telemetryData.armed;
            elements.armedStatus.textContent = armed ? 'ARMED' : 'DISARMED';
            elements.armedStatus.className = `armed-status ${armed ? 'armed' : ''}`;
        }

        // Flight mode
        if (elements.flightMode) {
            const mode = telemetryData.mode || 'UNKNOWN';
            elements.flightMode.textContent = `Mode: ${mode}`;
        }

        // Battery voltage
        if (elements.batteryVoltage) {
            const voltage = telemetryData.battery_voltage || 0;
            elements.batteryVoltage.textContent = `Bat: ${voltage.toFixed(1)} V`;
        }

        // Current draw
        if (elements.currentDraw) {
            const current = telemetryData.current || 0;
            elements.currentDraw.textContent = `Cur: ${current.toFixed(1)} A`;
        }

        // GPS status
        if (elements.gpsStatus) {
            const fixType = telemetryData.gps_fix_type || 0;
            const sats = telemetryData.satellites_visible || 0;
            const hdop = telemetryData.hdop || 99.9;

            const fixTypes = ['NO_GPS', 'NO_FIX', '2D_FIX', '3D_FIX', 'DGPS', 'RTK_FLOAT', 'RTK_FIXED'];
            const fixName = fixTypes[fixType] || 'UNKNOWN';

            elements.gpsStatus.textContent = `GPS: ${fixName} (${sats}) HDOP:${hdop.toFixed(1)}`;
        }

        // Position display
        if (elements.positionDisplay) {
            const lat = telemetryData.lat || 0;
            const lon = telemetryData.lon || 0;
            elements.positionDisplay.textContent = `${lat.toFixed(6)}, ${lon.toFixed(6)}`;
        }
    }

    /**
     * Handle Window Resize
     */
    function handleResize() {
        // Reinitialize canvases with new dimensions
        setTimeout(() => {
            initializeCanvases();
        }, 100);
    }

    /**
     * Event Handlers
     */
    function handleTelemetryUpdate(event) {
        const data = event.detail || event;
        if (data) {
            telemetryData = { ...telemetryData, ...data };
        }
    }

    function handleConnectionChange(event) {
        const data = event.detail || event;
        if (data && !data.connected) {
            // Reset data on disconnect
            telemetryData = {};
        }
    }

    /**
     * Public API
     */
    return {
        initialize: initialize,

        // Data getters
        getTelemetryData: () => ({ ...telemetryData }),

        // Module lifecycle callbacks
        onTelemetryUpdate: handleTelemetryUpdate,
        onConnectionChange: handleConnectionChange,
        onResize: handleResize,

        // Cleanup
        destroy: () => {
            if (animationFrameId) {
                cancelAnimationFrame(animationFrameId);
            }
        }
    };
})();

