/**
 * Update Professional Textual Displays
 */
function updateTextualDisplays() {
    // Professional Flight Mode Display (overlay on attitude indicator)
    const flightModeDisplay = document.getElementById('flight-mode-display');
    if (flightModeDisplay) {
        const mode = telemetryData.mode || 'UNKNOWN';
        const armed = telemetryData.armed;

        // Aviation-style mode abbreviations
        const modeAbbreviations = {
            'STABILIZE': 'STAB',
            'ALT_HOLD': 'ALT',
            'POS_HOLD': 'POS',
            'LOITER': 'LOIT',
            'GUIDED': 'GUID',
            'RTL': 'RTL',
            'LAND': 'LAND',
            'AUTO': 'AUTO',
            'BRAKE': 'BRK'
        };

        const modeText = modeAbbreviations[mode] || mode;
        flightModeDisplay.textContent = armed ? `${modeText} ARMED` : `${modeText} SAFE`;
        flightModeDisplay.style.color = armed ? '#FF4444' : '#00FF00';
        flightModeDisplay.style.borderColor = armed ? '#FF4444' : '#00AA00';
    }

    // Armed status with professional styling
    if (elements.armedStatus) {
        const armed = telemetryData.armed;
        elements.armedStatus.textContent = armed ? 'ARMED' : 'DISARMED';
        elements.armedStatus.className = `armed-status ${armed ? 'armed' : ''}`;
        elements.armedStatus.style.backgroundColor = armed ? '#FF4444' : '#666666';
        elements.armedStatus.style.animation = armed ? 'pulse 1s infinite' : 'none';
    }

    // Legacy flight mode display
    if (elements.flightMode) {
        const mode = telemetryData.mode || 'UNKNOWN';
        elements.flightMode.textContent = `Mode: ${mode}`;
    }

    // Professional battery display with color coding
    if (elements.batteryVoltage) {
        const voltage = telemetryData.battery_voltage || 0;
        elements.batteryVoltage.textContent = `BAT ${voltage.toFixed(1)}V`;

        // Color coding based on battery voltage (typical 3S-4S LiPo)
        if (voltage > 12.6) {
            elements.batteryVoltage.style.color = '#00FF00'; // Green - good
        } else if (voltage > 11.1) {
            elements.batteryVoltage.style.color = '#FFFF00'; // Yellow - caution
        } else {
            elements.batteryVoltage.style.color = '#FF4444'; // Red - low
        }
    }

    // Professional current draw display
    if (elements.currentDraw) {
        const current = telemetryData.current || 0;
        elements.currentDraw.textContent = `${current.toFixed(1)}A`;

        // Color coding for current draw
        elements.currentDraw.style.color = current > 20 ? '#FFFF00' : '#00FF00';
    }

    // Professional GPS status with WAAS-style display
    if (elements.gpsStatus) {
        const fixType = telemetryData.gps_fix_type || 0;
        const sats = telemetryData.satellites_visible || 0;
        const hdop = telemetryData.hdop || 99.9;

        const fixTypes = ['NO GPS', 'NO FIX', '2D', '3D', 'DGPS', 'RTK FL', 'RTK FX'];
        const fixName = fixTypes[fixType] || 'UNK';

        elements.gpsStatus.textContent = `GPS ${fixName} ${sats}SAT ${hdop.toFixed(1)}`;

        // Color coding for GPS quality
        if (fixType >= 3 && hdop < 2.0) {
            elements.gpsStatus.style.color = '#00FF00'; // Green - excellent
        } else if (fixType >= 2 && hdop < 5.0) {
            elements.gpsStatus.style.color = '#FFFF00'; // Yellow - usable
        } else {
            elements.gpsStatus.style.color = '#FF4444'; // Red - poor
        }
    }

    // Professional position display with aviation format
    if (elements.positionDisplay) {
        const lat = telemetryData.lat || 0;
        const lon = telemetryData.lon || 0;

        // Format coordinates in degrees/minutes/seconds or decimal as appropriate
        const latFormatted = formatCoordinate(lat, 'lat');
        const lonFormatted = formatCoordinate(lon, 'lon');

        elements.positionDisplay.textContent = `${latFormatted} ${lonFormatted}`;
        elements.positionDisplay.style.fontFamily = '"Courier New", monospace';
    }
}

/**
 * Format coordinates in aviation style
 */
function formatCoordinate(coord, type) {
    if (coord === 0) return type === 'lat' ? 'LAT 00.000000' : 'LON 000.000000';

    const abs = Math.abs(coord);
    const direction = type === 'lat' ? (coord >= 0 ? 'N' : 'S') : (coord >= 0 ? 'E' : 'W');
    const formatted = abs.toFixed(6).padStart(type === 'lat' ? 9 : 10, '0');

    return `${formatted}${direction}`;
}

