/**
 * WebGCS Telemetry Display Module
 * Handles Primary Flight Display (PFD) with attitude indicator and instrument tapes
 */

window.TelemetryDisplay = (function() {
    'use strict';

    // Private variables
    let telemetryData = {};
    let animationFrameId = null;

    // Canvas contexts
    let contexts = {};

    // DOM elements
    let elements = {};

    /**
     * Initialize Telemetry Display
     */
    function initialize() {
        console.log('Initializing Telemetry Display...');

        // Cache DOM elements
        cacheElements();

        // Initialize canvases
        initializeCanvases();

        // Setup event listeners
        setupEventListeners();

        // Start animation loop
        startAnimationLoop();

        console.log('Telemetry Display initialized');
    }

    /**
     * Cache DOM Elements
     */
    function cacheElements() {
        elements = {
            // Canvas elements
            attitudeIndicator: document.getElementById('attitude-indicator'),
            airspeedTape: document.getElementById('airspeed-tape'),
            altitudeTape: document.getElementById('altitude-tape'),

            // Status elements
            armedStatus: document.getElementById('armed-status'),
            flightMode: document.getElementById('flight-mode'),

            // Telemetry elements
            batteryVoltage: document.getElementById('battery-voltage'),
            currentDraw: document.getElementById('current-draw'),
            gpsStatus: document.getElementById('gps-status'),
            positionDisplay: document.getElementById('position-display')
        };

        // Check for missing elements
        Object.entries(elements).forEach(([key, element]) => {
            if (!element) {
                console.warn(`Telemetry Display: Element '${key}' not found`);
            }
        });
    }

    /**
     * Initialize Canvas Contexts
     */
    function initializeCanvases() {
        const canvasElements = ['attitudeIndicator', 'airspeedTape', 'altitudeTape'];

        canvasElements.forEach(name => {
            const canvas = elements[name];
            if (canvas && canvas.getContext) {
                contexts[name] = canvas.getContext('2d');

                // Set high DPI support
                const ctx = contexts[name];
                const dpr = window.devicePixelRatio || 1;
                const rect = canvas.getBoundingClientRect();

                canvas.width = rect.width * dpr;
                canvas.height = rect.height * dpr;
                ctx.scale(dpr, dpr);

                // Set initial styling
                ctx.textAlign = 'center';
                ctx.textBaseline = 'middle';
                ctx.font = '12px Arial, sans-serif';
            }
        });
    }

    /**
     * Setup Event Listeners
     */
    function setupEventListeners() {
        // Listen for global events
        if (window.WebGCS && window.WebGCS.eventBus) {
            window.WebGCS.eventBus.addEventListener('telemetry_updated', handleTelemetryUpdate);
            window.WebGCS.eventBus.addEventListener('connection_changed', handleConnectionChange);
        }

        // Handle window resize for canvas scaling
        window.addEventListener('resize', handleResize);
    }

    /**
     * Start Animation Loop
     */
    function startAnimationLoop() {
        function animate() {
            updateAllDisplays();
            animationFrameId = requestAnimationFrame(animate);
        }
        animate();
    }

    /**
     * Update All Displays
     */
    function updateAllDisplays() {
        drawAttitudeIndicator();
        drawAirspeedTape();
        drawAltitudeTape();
        updateTextualDisplays();
    }

    /**
     * Draw Professional Attitude Indicator (G1000-style Artificial Horizon)
     */
    function drawAttitudeIndicator() {
        const ctx = contexts.attitudeIndicator;
        if (!ctx) return;

        const canvas = elements.attitudeIndicator;
        const width = canvas.clientWidth;
        const height = canvas.clientHeight;
        const centerX = width / 2;
        const centerY = height / 2;
        const radius = Math.min(width, height) / 2 - 20;

        // Clear canvas with dark background
        ctx.fillStyle = '#000011';
        ctx.fillRect(0, 0, width, height);

        // Get attitude data
        const pitch = telemetryData.pitch || 0; // In degrees
        const roll = telemetryData.roll || 0;   // In degrees

        // Save context
        ctx.save();

        // Translate to center
        ctx.translate(centerX, centerY);

        // Draw horizon background
        ctx.save();

        // Rotate by roll angle
        ctx.rotate(roll * Math.PI / 180);

        // Create clipping circle
        ctx.beginPath();
        ctx.arc(0, 0, radius, 0, Math.PI * 2);
        ctx.clip();

        // Calculate pitch offset (aviation standard: 4 pixels per degree)
        const pitchPixels = pitch * 4;

        // Draw sky gradient (aviation blue)
        const skyGradient = ctx.createLinearGradient(0, -radius, 0, pitchPixels);
        skyGradient.addColorStop(0, '#4169E1'); // Royal blue at top
        skyGradient.addColorStop(1, '#87CEEB'); // Sky blue at horizon
        ctx.fillStyle = skyGradient;
        ctx.fillRect(-radius, -radius, radius * 2, radius + pitchPixels);

        // Draw ground gradient (aviation brown)
        const groundGradient = ctx.createLinearGradient(0, pitchPixels, 0, radius);
        groundGradient.addColorStop(0, '#8B4513'); // Saddle brown at horizon
        groundGradient.addColorStop(1, '#2F1B14'); // Dark brown at bottom
        ctx.fillStyle = groundGradient;
        ctx.fillRect(-radius, pitchPixels, radius * 2, radius * 2);

        // Draw horizon line (white)
        ctx.strokeStyle = '#FFFFFF';
        ctx.lineWidth = 3;
        ctx.beginPath();
        ctx.moveTo(-radius, pitchPixels);
        ctx.lineTo(radius, pitchPixels);
        ctx.stroke();

        // Draw professional pitch ladder
        drawPitchLadder(ctx, radius, pitchPixels);

        ctx.restore();

        // Draw professional aircraft symbol (white chevron bars)
        drawAircraftSymbol(ctx);

        // Draw outer bezel
        ctx.strokeStyle = '#4169E1';
        ctx.lineWidth = 3;
        ctx.beginPath();
        ctx.arc(0, 0, radius, 0, Math.PI * 2);
        ctx.stroke();

        // Draw professional roll scale
        drawProfessionalRollScale(ctx, radius);

        ctx.restore();
    }

    /**
     * Draw Professional Pitch Ladder (G1000-style)
     */
    function drawPitchLadder(ctx, radius, pitchOffset) {
        const pitchAngles = [-60, -45, -30, -20, -15, -10, -5, 0, 5, 10, 15, 20, 30, 45, 60];

        ctx.font = '12px "Courier New", monospace';
        ctx.textAlign = 'center';
        ctx.lineWidth = 2;

        pitchAngles.forEach(angle => {
            if (angle === 0) return; // Skip horizon line (already drawn)

            const y = pitchOffset - (angle * 4); // 4 pixels per degree

            if (Math.abs(y) > radius) return; // Skip if outside visible area

            const isAboveHorizon = angle > 0;
            const isMajorLine = Math.abs(angle) % 10 === 0;
            const lineLength = isMajorLine ? 80 : 40;
            const lineStyle = isMajorLine ? 2 : 1;

            // Set colors based on sky/ground
            ctx.strokeStyle = '#FFFFFF';
            ctx.fillStyle = '#FFFFFF';
            ctx.lineWidth = lineStyle;

            if (isMajorLine) {
                // Major pitch lines (solid)
                ctx.beginPath();
                ctx.moveTo(-lineLength / 2, y);
                ctx.lineTo(lineLength / 2, y);
                ctx.stroke();

                // Pitch angle numbers
                ctx.fillText(Math.abs(angle).toString(), -lineLength / 2 - 20, y + 4);
                ctx.fillText(Math.abs(angle).toString(), lineLength / 2 + 20, y + 4);
            } else if (Math.abs(angle) === 2.5 || Math.abs(angle) === 5) {
                // Minor pitch lines
                ctx.setLineDash([5, 5]);
                ctx.beginPath();
                ctx.moveTo(-lineLength / 2, y);
                ctx.lineTo(lineLength / 2, y);
                ctx.stroke();
                ctx.setLineDash([]);
            }

            // Draw chevron for 5-degree lines
            if (Math.abs(angle) % 5 === 0 && Math.abs(angle) % 10 !== 0) {
                const chevronSize = 8;
                ctx.beginPath();
                if (isAboveHorizon) {
                    // Upward chevron for climb
                    ctx.moveTo(-chevronSize, y + chevronSize);
                    ctx.lineTo(0, y);
                    ctx.lineTo(chevronSize, y + chevronSize);
                } else {
                    // Downward chevron for dive
                    ctx.moveTo(-chevronSize, y - chevronSize);
                    ctx.lineTo(0, y);
                    ctx.lineTo(chevronSize, y - chevronSize);
                }
                ctx.stroke();
            }
        });
    }

    /**
     * Draw Professional Aircraft Symbol (White Chevron Bars)
     */
    function drawAircraftSymbol(ctx) {
        ctx.strokeStyle = '#FFFFFF';
        ctx.fillStyle = '#FFFFFF';
        ctx.lineWidth = 3;

        // Center reference dot
        ctx.beginPath();
        ctx.arc(0, 0, 2, 0, Math.PI * 2);
        ctx.fill();

        // Left wing bar
        ctx.beginPath();
        ctx.moveTo(-35, 0);
        ctx.lineTo(-8, 0);
        ctx.lineTo(-8, -3);
        ctx.stroke();

        // Right wing bar
        ctx.beginPath();
        ctx.moveTo(35, 0);
        ctx.lineTo(8, 0);
        ctx.lineTo(8, -3);
        ctx.stroke();

        // Center fuselage reference
        ctx.beginPath();
        ctx.moveTo(0, -8);
        ctx.lineTo(0, 8);
        ctx.lineWidth = 2;
        ctx.stroke();
    }

    /**
     * Draw Professional Roll Scale (G1000-style Bank Angle Indicator)
     */
    function drawProfessionalRollScale(ctx, radius) {
        const roll = telemetryData.roll || 0;

        // Draw bank angle marks
        ctx.strokeStyle = '#FFFFFF';
        ctx.fillStyle = '#FFFFFF';
        ctx.lineWidth = 2;
        ctx.font = '11px "Courier New", monospace';
        ctx.textAlign = 'center';

        // Standard bank angle marks: 10°, 20°, 30°, 45°, 60°, 90°
        const bankMarks = [
            { angle: -90, length: 15, showNumber: true },
            { angle: -60, length: 12, showNumber: true },
            { angle: -45, length: 12, showNumber: true },
            { angle: -30, length: 10, showNumber: true },
            { angle: -20, length: 8, showNumber: false },
            { angle: -10, length: 8, showNumber: false },
            { angle: 0, length: 15, showNumber: false },
            { angle: 10, length: 8, showNumber: false },
            { angle: 20, length: 8, showNumber: false },
            { angle: 30, length: 10, showNumber: true },
            { angle: 45, length: 12, showNumber: true },
            { angle: 60, length: 12, showNumber: true },
            { angle: 90, length: 15, showNumber: true }
        ];

        bankMarks.forEach(mark => {
            const radian = (mark.angle - 90) * Math.PI / 180;
            const x1 = Math.cos(radian) * (radius - mark.length);
            const y1 = Math.sin(radian) * (radius - mark.length);
            const x2 = Math.cos(radian) * radius;
            const y2 = Math.sin(radian) * radius;

            ctx.beginPath();
            ctx.moveTo(x1, y1);
            ctx.lineTo(x2, y2);
            ctx.stroke();

            if (mark.showNumber && Math.abs(mark.angle) !== 90) {
                const textX = Math.cos(radian) * (radius + 15);
                const textY = Math.sin(radian) * (radius + 15);
                ctx.fillText(Math.abs(mark.angle).toString(), textX, textY + 4);
            }
        });

        // Draw roll pointer (inverted triangle)
        ctx.save();
        ctx.rotate(roll * Math.PI / 180);
        ctx.fillStyle = '#FFFF00'; // Yellow roll indicator
        ctx.strokeStyle = '#FFFFFF';
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(0, -radius - 8);
        ctx.lineTo(-6, -radius + 2);
        ctx.lineTo(6, -radius + 2);
        ctx.closePath();
        ctx.fill();
        ctx.stroke();
        ctx.restore();
    }

    // Old roll scale function removed - replaced with drawProfessionalRollScale

    /**
     * Draw Professional Airspeed Tape (G1000-style)
     */
    function drawAirspeedTape() {
        const ctx = contexts.airspeedTape;
        if (!ctx) return;

        const canvas = elements.airspeedTape;
        const width = canvas.clientWidth;
        const height = canvas.clientHeight;

        // Clear canvas with dark gradient background
        const bgGradient = ctx.createLinearGradient(0, 0, width, 0);
        bgGradient.addColorStop(0, '#000011');
        bgGradient.addColorStop(1, '#000022');
        ctx.fillStyle = bgGradient;
        ctx.fillRect(0, 0, width, height);

        // Get airspeed data (convert m/s to knots for aviation standard)
        const groundSpeed = Math.sqrt(
            Math.pow(telemetryData.vx || 0, 2) + 
            Math.pow(telemetryData.vy || 0, 2)
        );
        const airspeedKnots = groundSpeed * 1.94384; // m/s to knots conversion

        const centerY = height / 2;
        const pixelsPerKnot = 3; // 3 pixels per knot (aviation standard)

        // Draw speed scale
        ctx.font = '12px "Courier New", monospace';
        ctx.textAlign = 'right';
        ctx.lineWidth = 1;

        const minSpeed = Math.max(0, Math.floor((airspeedKnots - 40) / 10) * 10);
        const maxSpeed = Math.ceil((airspeedKnots + 40) / 10) * 10;

        for (let speed = minSpeed; speed <= maxSpeed; speed += 5) {
            const y = centerY - (speed - airspeedKnots) * pixelsPerKnot;

            if (y >= 10 && y <= height - 10) {
                const isMajorMark = speed % 10 === 0;

                if (isMajorMark) {
                    // Major marks (every 10 knots)
                    ctx.strokeStyle = '#32CD32'; // Lime green
                    ctx.fillStyle = '#32CD32';
                    ctx.beginPath();
                    ctx.moveTo(width - 15, y);
                    ctx.lineTo(width, y);
                    ctx.stroke();

                    // Speed numbers
                    ctx.fillText(speed.toString(), width - 20, y + 4);
                } else {
                    // Minor marks (every 5 knots)
                    ctx.strokeStyle = '#228B22'; // Forest green
                    ctx.beginPath();
                    ctx.moveTo(width - 8, y);
                    ctx.lineTo(width, y);
                    ctx.stroke();
                }
            }
        }

        // Draw V-speed color bands (if applicable)
        drawVSpeedBands(ctx, width, height, centerY, pixelsPerKnot, airspeedKnots);

        // Draw current airspeed readout box
        const boxWidth = 45;
        const boxHeight = 24;
        const boxX = 2;
        const boxY = centerY - boxHeight / 2;

        // Readout box background
        ctx.fillStyle = '#000000';
        ctx.strokeStyle = '#32CD32';
        ctx.lineWidth = 2;
        ctx.fillRect(boxX, boxY, boxWidth, boxHeight);
        ctx.strokeRect(boxX, boxY, boxWidth, boxHeight);

        // Airspeed readout text
        ctx.fillStyle = '#32CD32';
        ctx.textAlign = 'center';
        ctx.font = '14px "Courier New", monospace';
        ctx.fillText(Math.round(airspeedKnots).toString(), boxX + boxWidth / 2, centerY + 4);

        // Speed trend vector (6-second predictor)
        drawSpeedTrendVector(ctx, width, centerY, airspeedKnots, pixelsPerKnot);
    }

    /**
     * Draw V-Speed Color Bands (Aviation Standard)
     */
    function drawVSpeedBands(ctx, width, height, centerY, pixelsPerKnot, currentSpeed) {
        // Standard V-speeds for small aircraft (these would be configurable in real system)
        const vSpeeds = {
            vs0: 35,    // Stall speed (landing config) - red line
            vs1: 40,    // Stall speed (clean config) - red line  
            vno: 120,   // Normal operating speed - yellow arc start
            vne: 150,   // Never exceed speed - red line
            vfe: 75,    // Flap extended speed - white arc end
            vmc: 45     // Minimum control speed
        };

        // Draw color bands on left edge
        const bandWidth = 4;

        // White arc (flap operating range)
        ctx.fillStyle = '#FFFFFF';
        const whiteStart = centerY - (vSpeeds.vfe - currentSpeed) * pixelsPerKnot;
        const whiteEnd = centerY - (vSpeeds.vs0 - currentSpeed) * pixelsPerKnot;
        if (whiteStart >= 0 && whiteEnd <= height) {
            ctx.fillRect(0, whiteStart, bandWidth, whiteEnd - whiteStart);
        }

        // Green arc (normal operating range)
        ctx.fillStyle = '#00AA00';
        const greenStart = centerY - (vSpeeds.vno - currentSpeed) * pixelsPerKnot;
        const greenEnd = centerY - (vSpeeds.vs1 - currentSpeed) * pixelsPerKnot;
        if (greenStart >= 0 && greenEnd <= height) {
            ctx.fillRect(0, greenStart, bandWidth, greenEnd - greenStart);
        }

        // Yellow arc (caution range)
        ctx.fillStyle = '#FFFF00';
        const yellowStart = centerY - (vSpeeds.vne - currentSpeed) * pixelsPerKnot;
        const yellowEnd = centerY - (vSpeeds.vno - currentSpeed) * pixelsPerKnot;
        if (yellowStart >= 0 && yellowEnd <= height) {
            ctx.fillRect(0, yellowStart, bandWidth, yellowEnd - yellowStart);
        }
    }

    /**
     * Draw Speed Trend Vector (6-second speed predictor)
     */
    function drawSpeedTrendVector(ctx, width, centerY, currentSpeed, pixelsPerKnot) {
        // Calculate speed trend (simplified - would use actual acceleration in real system)
        const speedTrend = 0; // Placeholder - would calculate from telemetry data

        if (Math.abs(speedTrend) > 1) { // Only show if significant trend
            const trendLength = speedTrend * pixelsPerKnot * 6; // 6-second prediction

            ctx.strokeStyle = '#FF00FF'; // Magenta trend vector
            ctx.lineWidth = 2;
            ctx.beginPath();
            ctx.moveTo(width - 5, centerY);
            ctx.lineTo(width - 5, centerY - trendLength);
            ctx.stroke();

            // Arrow head
            ctx.beginPath();
            if (trendLength > 0) {
                ctx.moveTo(width - 8, centerY - trendLength + 3);
                ctx.lineTo(width - 5, centerY - trendLength);
                ctx.lineTo(width - 2, centerY - trendLength + 3);
            } else {
                ctx.moveTo(width - 8, centerY - trendLength - 3);
                ctx.lineTo(width - 5, centerY - trendLength);
                ctx.lineTo(width - 2, centerY - trendLength - 3);
            }
            ctx.stroke();
        }
    }

    /**
     * Draw Professional Altitude Tape (G1000-style)
     */
    function drawAltitudeTape() {
        const ctx = contexts.altitudeTape;
        if (!ctx) return;

        const canvas = elements.altitudeTape;
        const width = canvas.clientWidth;
        const height = canvas.clientHeight;

        // Clear canvas with dark gradient background
        const bgGradient = ctx.createLinearGradient(0, 0, width, 0);
        bgGradient.addColorStop(0, '#000022');
        bgGradient.addColorStop(1, '#000011');
        ctx.fillStyle = bgGradient;
        ctx.fillRect(0, 0, width, height);

        // Get altitude data (convert meters to feet for aviation standard)
        const altitudeMeters = telemetryData.alt_rel || 0;
        const altitudeFeet = altitudeMeters * 3.28084; // meters to feet conversion

        const centerY = height / 2;
        const pixelsPerFoot = 0.2; // 0.2 pixels per foot (aviation standard scaling)

        // Draw altitude scale
        ctx.font = '12px "Courier New", monospace';
        ctx.textAlign = 'left';
        ctx.lineWidth = 1;

        // Round to nearest 50 feet for scale
        const minAlt = Math.floor((altitudeFeet - 400) / 100) * 100;
        const maxAlt = Math.ceil((altitudeFeet + 400) / 100) * 100;

        for (let alt = minAlt; alt <= maxAlt; alt += 50) {
            const y = centerY - (alt - altitudeFeet) * pixelsPerFoot;

            if (y >= 10 && y <= height - 10) {
                const isMajorMark = alt % 100 === 0;

                if (isMajorMark) {
                    // Major marks (every 100 feet)
                    ctx.strokeStyle = '#FF6B35'; // Orange-red
                    ctx.fillStyle = '#FF6B35';
                    ctx.beginPath();
                    ctx.moveTo(0, y);
                    ctx.lineTo(15, y);
                    ctx.stroke();

                    // Altitude numbers
                    const altDisplay = alt >= 0 ? alt.toString() : '';
                    ctx.fillText(altDisplay, 18, y + 4);
                } else {
                    // Minor marks (every 50 feet)
                    ctx.strokeStyle = '#CC5522';
                    ctx.beginPath();
                    ctx.moveTo(0, y);
                    ctx.lineTo(8, y);
                    ctx.stroke();
                }
            }
        }

        // Draw barometric pressure setting area (top of tape)
        drawBarometricSetting(ctx, width);

        // Draw current altitude readout box
        const boxWidth = 55;
        const boxHeight = 26;
        const boxX = width - boxWidth - 2;
        const boxY = centerY - boxHeight / 2;

        // Readout box background
        ctx.fillStyle = '#000000';
        ctx.strokeStyle = '#FF6B35';
        ctx.lineWidth = 2;
        ctx.fillRect(boxX, boxY, boxWidth, boxHeight);
        ctx.strokeRect(boxX, boxY, boxWidth, boxHeight);

        // Altitude readout text
        ctx.fillStyle = '#FF6B35';
        ctx.textAlign = 'center';
        ctx.font = '14px "Courier New", monospace';
        ctx.fillText(Math.round(altitudeFeet).toString(), boxX + boxWidth / 2, centerY + 4);

        // Altitude trend vector (6-second predictor)
        drawAltitudeTrendVector(ctx, width, centerY, altitudeFeet, pixelsPerFoot);

        // Ground reference line (when applicable)
        drawGroundReference(ctx, width, height, centerY, altitudeFeet, pixelsPerFoot);
    }

    /**
     * Draw Barometric Pressure Setting (Kollsman Window)
     */
    function drawBarometricSetting(ctx, width) {
        const baroPressure = 29.92; // Standard pressure - would be configurable

        ctx.fillStyle = '#000000';
        ctx.strokeStyle = '#FF6B35';
        ctx.lineWidth = 1;
        ctx.fillRect(2, 5, width - 4, 20);
        ctx.strokeRect(2, 5, width - 4, 20);

        ctx.fillStyle = '#00FF00';
        ctx.font = '10px "Courier New", monospace';
        ctx.textAlign = 'center';
        ctx.fillText(`${baroPressure.toFixed(2)}"`, width / 2, 18);
    }

    /**
     * Draw Altitude Trend Vector (Vertical Speed Indicator)
     */
    function drawAltitudeTrendVector(ctx, width, centerY, currentAlt, pixelsPerFoot) {
        // Calculate vertical speed from telemetry (m/s to ft/min)
        const verticalSpeedMS = telemetryData.vz || 0;
        const verticalSpeedFPM = verticalSpeedMS * 196.85; // m/s to ft/min

        if (Math.abs(verticalSpeedFPM) > 50) { // Only show if significant vertical speed
            const trendLength = (verticalSpeedFPM / 60) * pixelsPerFoot * 6; // 6-second prediction

            ctx.strokeStyle = '#FF00FF'; // Magenta trend vector
            ctx.lineWidth = 2;
            ctx.beginPath();
            ctx.moveTo(width - 8, centerY);
            ctx.lineTo(width - 8, centerY - trendLength);
            ctx.stroke();

            // Arrow head
            ctx.beginPath();
            if (trendLength < 0) { // Climbing
                ctx.moveTo(width - 11, centerY - trendLength + 3);
                ctx.lineTo(width - 8, centerY - trendLength);
                ctx.lineTo(width - 5, centerY - trendLength + 3);
            } else { // Descending
                ctx.moveTo(width - 11, centerY - trendLength - 3);
                ctx.lineTo(width - 8, centerY - trendLength);
                ctx.lineTo(width - 5, centerY - trendLength - 3);
            }
            ctx.stroke();
        }
    }

    /**
     * Draw Ground Reference Line
     */
    function drawGroundReference(ctx, width, height, centerY, currentAltFeet, pixelsPerFoot) {
        // Draw ground reference if within display range
        const groundY = centerY - (0 - currentAltFeet) * pixelsPerFoot;

        if (groundY >= 0 && groundY <= height) {
            ctx.strokeStyle = '#8B4513'; // Brown ground line
            ctx.lineWidth = 3;
            ctx.beginPath();
            ctx.moveTo(0, groundY);
            ctx.lineTo(width, groundY);
            ctx.stroke();

            // Ground label
            ctx.fillStyle = '#8B4513';
            ctx.font = '10px "Courier New", monospace';
            ctx.textAlign = 'center';
            ctx.fillText('GND', width / 2, groundY - 5);
        }
    }

    /**
     * Update Textual Displays
     */
    function updateTextualDisplays() {
        // Armed status
        if (elements.armedStatus) {
            const armed = telemetryData.armed;
            elements.armedStatus.textContent = armed ? 'ARMED' : 'DISARMED';
            elements.armedStatus.className = `armed-status ${armed ? 'armed' : ''}`;
        }

        // Flight mode
        if (elements.flightMode) {
            const mode = telemetryData.mode || 'UNKNOWN';
            elements.flightMode.textContent = `Mode: ${mode}`;
        }

        // Battery voltage
        if (elements.batteryVoltage) {
            const voltage = telemetryData.battery_voltage || 0;
            elements.batteryVoltage.textContent = `Bat: ${voltage.toFixed(1)} V`;
        }

        // Current draw
        if (elements.currentDraw) {
            const current = telemetryData.current || 0;
            elements.currentDraw.textContent = `Cur: ${current.toFixed(1)} A`;
        }

        // GPS status
        if (elements.gpsStatus) {
            const fixType = telemetryData.gps_fix_type || 0;
            const sats = telemetryData.satellites_visible || 0;
            const hdop = telemetryData.hdop || 99.9;

            const fixTypes = ['NO_GPS', 'NO_FIX', '2D_FIX', '3D_FIX', 'DGPS', 'RTK_FLOAT', 'RTK_FIXED'];
            const fixName = fixTypes[fixType] || 'UNKNOWN';

            elements.gpsStatus.textContent = `GPS: ${fixName} (${sats}) HDOP:${hdop.toFixed(1)}`;
        }

        // Position display
        if (elements.positionDisplay) {
            const lat = telemetryData.lat || 0;
            const lon = telemetryData.lon || 0;
            elements.positionDisplay.textContent = `${lat.toFixed(6)}, ${lon.toFixed(6)}`;
        }
    }

    /**
     * Handle Window Resize
     */
    function handleResize() {
        // Reinitialize canvases with new dimensions
        setTimeout(() => {
            initializeCanvases();
        }, 100);
    }

    /**
     * Event Handlers
     */
    function handleTelemetryUpdate(event) {
        const data = event.detail || event;
        if (data) {
            telemetryData = { ...telemetryData, ...data };
        }
    }

    function handleConnectionChange(event) {
        const data = event.detail || event;
        if (data && !data.connected) {
            // Reset data on disconnect
            telemetryData = {};
        }
    }

    /**
     * Public API
     */
    return {
        initialize: initialize,

        // Data getters
        getTelemetryData: () => ({ ...telemetryData }),

        // Module lifecycle callbacks
        onTelemetryUpdate: handleTelemetryUpdate,
        onConnectionChange: handleConnectionChange,
        onResize: handleResize,

        // Cleanup
        destroy: () => {
            if (animationFrameId) {
                cancelAnimationFrame(animationFrameId);
            }
        }
    };
})();

