    padding-bottom: 0.4rem;
}

.panel h4 {
    color: var(--text-color);
    margin-bottom: 0.75rem;
    font-size: 1rem;
    font-weight: 500;
}

/* Connection Management Styles */
.connection-status {
    margin-bottom: 1rem;
}

.status-indicator {
    padding: 0.75rem;
    border-radius: 4px;
