}

.status-indicator.backend-connected {
    background: #d4edda;
    color: #155724;
    border: 1px solid #c3e6cb;
}

.heartbeat-section {
    display: flex;
    align-items: center;
    gap: 1rem;
    padding: 0.5rem;
    background: var(--light-color);
    border-radius: 4px;
}

.heartbeat-icon {
    font-size: 1.5rem;
    transition: transform 0.3s ease;
}

.heartbeat-icon.pulse {
    transform: scale(1.2);
}

.heartbeat-counter {
    font-weight: 600;
    color: var(--primary-color);
}

.heartbeat-controls {
    margin-left: auto;
}

.sound-toggle {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    cursor: pointer;
    font-size: 0.9rem;
}

.connection-inputs {
    display: grid;
    grid-template-columns: 1fr 100px;
    gap: 0.5rem;
