.close-btn:hover {
    background: rgba(255, 255, 255, 0.2);
}

.panel-content {
    padding: 1rem;
    display: flex;
    flex-direction: column;
    gap: 1.5rem;
}

.internet-status {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.75rem;
    background: var(--light-color);
    border-radius: 4px;
}

.internet-status.online {
    background: #d4edda;
    color: #155724;
}

.internet-status.offline {
    background: #f8d7da;
    color: #721c24;
}

