    background: radial-gradient(circle at center, #000022 0%, #000011 100%);
    border: 2px solid #4169E1;
    box-shadow: 0 0 15px rgba(65, 105, 225, 0.4);
}

#airspeed-tape, #altitude-tape {
    background: linear-gradient(to bottom, #000011 0%, #000022 50%, #000011 100%);
    border: 2px solid #32CD32;
    box-shadow: 0 0 8px rgba(50, 205, 50, 0.3);
}

/* Professional Aviation-Style PFD Info Panel */
.pfd-info {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    background: linear-gradient(145deg, #000011, #000022);
    border-radius: 8px;
    padding: 0.75rem;
    border: 1px solid #333366;
}

.pfd-status {
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 0.5rem;
}

/* Professional Armed Status Indicator */
.armed-status {
    padding: 0.5rem 1rem;
    border-radius: 6px;
    font-weight: 700;
    font-size: 1rem;
    text-align: center;
    font-family: 'Courier New', monospace;
    background: #666666;
    color: white;
    border: 2px solid #888888;
    box-shadow: 0 0 5px rgba(255, 68, 68, 0.3);
    transition: all 0.3s ease;
}

.armed-status.armed {
    background: #FF4444;
    border-color: #FF6666;
    box-shadow: 0 0 10px rgba(255, 68, 68, 0.6);
    animation: pulse 2s infinite;
}

/* Legacy flight mode display with professional styling */
.flight-mode {
    padding: 0.5rem 1rem;
    background: linear-gradient(145deg, #001122, #002233);
    border-radius: 6px;
    font-weight: 600;
    font-family: 'Courier New', monospace;
    color: #00CCFF;
    border: 1px solid #0066CC;
}

/* Professional telemetry displays */
.pfd-telemetry {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.telemetry-row {
    display: flex;
    justify-content: space-between;
    gap: 0.5rem;
}

.telemetry-item {
    padding: 0.5rem;
    background: linear-gradient(145deg, #000022, #001133);
    border-radius: 4px;
    font-size: 0.85rem;
    font-weight: 600;
    font-family: 'Courier New', monospace;
    text-align: center;
    flex: 1;
    color: #00FF00;
    border: 1px solid #006600;
    box-shadow: 0 0 3px rgba(0, 255, 0, 0.3);
    transition: all 0.3s ease;
}

/* GPS status gets special aviation styling */
#gps-status {
    color: #00CCFF;
    border-color: #0066CC;
    box-shadow: 0 0 3px rgba(0, 204, 255, 0.3);
}

/* Position display with coordinate styling */
#position-display {
    font-size: 0.8rem;
    letter-spacing: 0.5px;
    color: #FFCC00;
    border-color: #CC9900;
    box-shadow: 0 0 3px rgba(255, 204, 0, 0.3);
}

/* Enhanced pulse animation for critical indicators */
@keyframes pulse {
    0%, 100% { 
        transform: scale(1);
        opacity: 1;
    }
    50% { 
        transform: scale(1.05);
        opacity: 0.8;
    }
}

/* Flight Controls Styles */
.control-groups {
    display: flex;
    flex-direction: column;
    gap: 1.5rem;
}

.control-group {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
}

.button-row {
    display: flex;
    gap: 0.5rem;
    align-items: center;
}

.takeoff-alt-row {
    display: flex;
    justify-content: center;
    margin-top: 0.5rem;
}

.alt-input {
    width: 80px;
    padding: 0.5rem;
    border: 1px solid var(--border-color);
    border-radius: 4px;
    font-size: 0.9rem;
    text-align: center;
}

.mode-select {
    padding: 0.5rem;
    border: 1px solid var(--border-color);
    border-radius: 4px;
    font-size: 0.9rem;
    margin-bottom: 0.5rem;
}

/* Navigation Controls Styles */
.nav-inputs {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    margin-bottom: 1rem;
}

.nav-buttons {
    display: flex;
    gap: 0.5rem;
}

/* Request Controls and Audio Styles */
.request-panel h3 {
    display: none;
}

.request-buttons {
    display: flex;
    gap: 0.5rem;
}

.audio-controls {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
}

.checkbox-label {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    cursor: pointer;
    font-size: 0.9rem;
}

/* Message Log Styles */
.message-log {
    height: 150px;
    overflow-y: auto;
    padding: 0.75rem;
    background: var(--light-color);
    border: 1px solid var(--border-color);
    border-radius: 4px;
    font-family: 'Courier New', monospace;
    font-size: 0.8rem;
}

.message-log .log-entry {
    margin-bottom: 0.25rem;
    padding: 0.25rem;
    border-radius: 2px;
}

.message-log .log-info {
    background: #d1ecf1;
    color: #0c5460;
}

.message-log .log-warning {
    background: #fff3cd;
    color: #856404;
}

.message-log .log-error {
    background: #f8d7da;
    color: #721c24;
}

/* Map Container Styles */
.map-container {
    position: relative;
    height: 100%;
    background: var(--panel-bg);
    border: 1px solid var(--border-color);
    border-radius: 8px;
    overflow: hidden;
}

.map-controls {
    position: absolute;
    top: 10px;
    left: 10px;
    z-index: 1000;
    display: flex;
    gap: 0.5rem;
    background: rgba(255, 255, 255, 0.9);
    padding: 0.5rem;
    border-radius: 4px;
    backdrop-filter: blur(5px);
}

.map {
    width: 100%;
    height: 100%;
}

/* Offline Maps Panel Styles */
.offline-maps-panel {
    position: absolute;
    top: 0;
    right: -400px;
    width: 400px;
    height: 100%;
    background: var(--panel-bg);
    border-left: 1px solid var(--border-color);
    transition: right 0.3s ease;
    z-index: 2000;
    overflow-y: auto;
}

.offline-maps-panel.active {
    right: 0;
}

.panel-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 1rem;
    background: var(--primary-color);
    color: white;
}

.panel-header h3 {
    margin: 0;
    color: white;
}

.close-btn {
    background: none;
    border: none;
    color: white;
    font-size: 1.5rem;
    cursor: pointer;
    padding: 0;
    width: 30px;
    height: 30px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 4px;
}

.close-btn:hover {
    background: rgba(255, 255, 255, 0.2);
}

.panel-content {
    padding: 1rem;
    display: flex;
    flex-direction: column;
    gap: 1.5rem;
}

.internet-status {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.75rem;
    background: var(--light-color);
    border-radius: 4px;
}

.internet-status.online {
    background: #d4edda;
    color: #155724;
}

.internet-status.offline {
    background: #f8d7da;
    color: #721c24;
}

.coord-inputs {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 0.5rem;
    margin-bottom: 1rem;
}

.input-row {
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
}

.input-row label {
    font-size: 0.9rem;
    font-weight: 500;
    color: var(--text-muted);
}

.input-row input {
    padding: 0.5rem;
    border: 1px solid var(--border-color);
    border-radius: 4px;
    font-size: 0.9rem;
}

.zoom-section {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 0.5rem;
    margin: 1rem 0;
}

.map-types {
    margin: 1rem 0;
}

.map-types label {
    display: block;
    margin-bottom: 0.5rem;
    cursor: pointer;
}

.download-info {
    padding: 1rem;
    background: var(--light-color);
    border-radius: 4px;
    margin: 1rem 0;
}

.download-controls {
    display: flex;
    gap: 0.5rem;
    margin-bottom: 1rem;
}

.progress-bar {
    width: 100%;
    height: 20px;
    background: var(--light-color);
    border-radius: 10px;
    overflow: hidden;
    margin-bottom: 0.5rem;
}

.progress-fill {
    height: 100%;
    background: var(--primary-color);
    width: 0%;
    transition: width 0.3s ease;
}

.cache-stats {
    background: var(--light-color);
    padding: 1rem;
    border-radius: 4px;
    margin-bottom: 1rem;
}

.cache-stats p {
    display: flex;
    justify-content: space-between;
    margin-bottom: 0.5rem;
}

.tips-section ul {
    padding-left: 1.5rem;
}

.tips-section li {
    margin-bottom: 0.5rem;
    color: var(--text-muted);
    font-size: 0.9rem;
}

/* Modal Styles */
.modal {
    display: none;
    position: fixed;
    z-index: 3000;
    left: 0;
    top: 0;
    width: 100%;
    height: 100%;
    background: rgba(0, 0, 0, 0.5);
    backdrop-filter: blur(3px);
}

.modal.active {
    display: flex;
    align-items: center;
    justify-content: center;
}

.modal-content {
    background: var(--panel-bg);
    padding: 2rem;
    border-radius: 8px;
    max-width: 400px;
    width: 90%;
    box-shadow: 0 4px 20px rgba(0, 0, 0, 0.3);
}

.modal-content h3 {
    margin-bottom: 1rem;
    color: var(--danger-color);
}

.modal-content p {
    margin-bottom: 1.5rem;
    color: var(--text-muted);
}

.modal-buttons {
    display: flex;
    gap: 0.5rem;
    justify-content: flex-end;
}

/* Responsive Design */
@media (max-width: 1200px) {
    .main-container {
        grid-template-columns: 320px 1fr;
    }

    .right-column {
        max-width: 700px;
    }
}

@media (max-width: 768px) {
    .main-container {
        grid-template-columns: 1fr;
        grid-template-rows: auto 1fr;
        height: auto;
        min-height: calc(100vh - 80px);
    }

    .left-column {
        max-height: none;
        order: 2;
    }

    .right-column {
        order: 1;
        height: 350px;
        max-width: none;
    }

    .main-header {
        padding: 0.75rem 1rem;
    }

    .main-header h1 {
        font-size: 1.4rem;
    }

    .header-controls {
        gap: 0.5rem;
    }

    .connection-inputs {
        grid-template-columns: 1fr;
    }

    .control-groups {
        gap: 1rem;
    }

    .button-row {
        flex-wrap: wrap;
    }

    .offline-maps-panel {
        width: 100%;
        right: -100%;
    }
}

/* Animation Classes */
.fade-in {
    animation: fadeIn 0.3s ease-in;
}

.pulse {
    animation: pulse 0.3s ease-in-out;
}

@keyframes fadeIn {
    from { opacity: 0; }
    to { opacity: 1; }
}

@keyframes pulse {
    0%, 100% { transform: scale(1); }
    50% { transform: scale(1.1); }
}

/* Utility Classes */
.text-center {
    text-align: center;
}

.text-muted {
    color: var(--text-muted);
}

.mt-1 { margin-top: 0.5rem; }
.mb-1 { margin-bottom: 0.5rem; }
.mt-2 { margin-top: 1rem; }
.mb-2 { margin-bottom: 1rem; }

.d-none {
    display: none !important;
}

.d-block {
    display: block !important;
}

.d-flex {
    display: flex !important;
}

/* Additional Message Log Styles */
.log-success {
    background: #d4edda;
    color: #155724;
    border: 1px solid #c3e6cb;
}

.log-debug {
    background: #f8f9fa;
    color: #495057;
    border: 1px solid #dee2e6;
}

.log-entry {
    padding: 0.25rem 0.5rem;
    border-radius: 3px;
    margin-bottom: 0.25rem;
    font-size: 0.85rem;
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.log-time {
    color: var(--text-muted);
    font-size: 0.8rem;
    min-width: 70px;
}

.log-icon {
    min-width: 20px;
    text-align: center;
}

.log-text {
    flex: 1;
    word-break: break-word;
}

