.pfd-status,
.pfd-telemetry,
.telemetry-row,
.telemetry-item,
.armed-status,
.flight-mode {
    display: none;
}

/* Animations for modern glass cockpit */
@keyframes pulse-armed {
    0%, 100% { 
        opacity: 1;
        transform: scale(1);
    }
    50% { 
        opacity: 0.8;
        transform: scale(1.02);
    }
